enum JackSnapshotDecodeState {
    AwaitToken,
    Decode(store::OwnedSchemaHexAuthority<JACK_OWNED_FIELD_BYTES>),
    Ready,
    Published,
    Closing,
    Complete,
}

struct JackSnapshotDecodeAuthority {
